#!/usr/bin/env python3
"""Publish two developer guides in this static site."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
public = root / "public"
date = "September 5, 2026"
iso = "2026-09-05T10:00:00+05:00"
posts = [
    ("codex-cli-ubuntu-openai-agent-guide", "How to Install Codex CLI and Connect Your OpenAI Account on Ubuntu", "Install OpenAI Codex on Ubuntu, sign in securely, run your first coding task, and use safe permissions with copy-ready commands.", "7 min", "1,080", "/images/codex-cli-banner.png", "OpenAI Codex CLI on Ubuntu", """<p>Codex CLI is OpenAI’s terminal coding agent. It can inspect a repository, edit files, run local tools, and help review changes. This guide uses the current official installer and signs in through the CLI—there is no need to paste a secret into a project file.</p><blockquote><p><strong>Before you begin:</strong> Use Ubuntu with an internet connection and a supported OpenAI/ChatGPT sign-in method. Run Codex only inside projects you trust.</p></blockquote><h2>1. Check your terminal tools</h2><pre><code>sudo apt update\nsudo apt install -y curl git\ngit --version\ncurl --version</code></pre><p><strong>Expected:</strong> Ubuntu reports installed versions for Git and curl.</p><h2>2. Install Codex CLI</h2><p>Run the official installer exactly as shown:</p><pre><code>curl -fsSL https://chatgpt.com/codex/install.sh | sh</code></pre><p><strong>Expected:</strong> The installer completes without errors. Close and reopen the terminal if the command is not yet available.</p><h2>3. Verify the installation</h2><pre><code>codex --version</code></pre><p><strong>Expected:</strong> A Codex version number, for example <code>codex x.y.z</code>.</p><h2>4. Open a project and connect your account</h2><pre><code>mkdir -p ~/Projects/demo-app\ncd ~/Projects/demo-app\ngit init\ncodex</code></pre><p><strong>Expected:</strong> Codex opens an interactive terminal session and presents an available sign-in method. Choose <strong>Sign in with ChatGPT</strong> (or another offered method), complete the browser flow, then return to the terminal. Never share your account password or access token in a repository.</p><h2>5. Run a first, read-only task</h2><p>Inside Codex, paste this prompt:</p><pre><code>Explain this project structure. Do not edit files or run commands.</code></pre><p><strong>Expected:</strong> Codex describes the directory and files it can inspect. This is a safe way to become familiar with a repository before making changes.</p><h2>6. Create project instructions</h2><p>Ask Codex to generate a project instruction file:</p><pre><code>/init</code></pre><p><strong>Expected:</strong> Codex proposes an <code>AGENTS.md</code> file. Review it before accepting; it should contain only project-specific development and test instructions.</p><h2>7. Work safely</h2><p>Use <code>/permissions</code> to see or adjust what Codex can do, and keep Git checkpoints around agent work:</p><pre><code>git status\ngit add -A\ngit commit -m \"Checkpoint before Codex task\"</code></pre><p>After an edit, inspect the result before committing:</p><pre><code>git diff\ngit status</code></pre><h2>Useful commands</h2><table><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>codex</code></td><td>Start an interactive session.</td></tr><tr><td><code>/status</code></td><td>Show session configuration.</td></tr><tr><td><code>/model</code></td><td>Choose an available model and reasoning effort.</td></tr><tr><td><code>/review</code></td><td>Review changes before committing.</td></tr><tr><td><code>codex exec "explain this project"</code></td><td>Run a repeatable non-interactive task.</td></tr></tbody></table><p>For changes in installation or account availability, refer to the <a href=\"https://learn.chatgpt.com/docs/codex/cli\">official OpenAI Codex CLI documentation</a>.</p>"""),
    ("claude-code-ubuntu-cli-guide", "How to Install Claude Code on Ubuntu: Complete CLI Guide", "Install Claude Code on Ubuntu, authenticate it safely, start an agent session, and use practical commands for everyday development.", "7 min", "1,020", "/images/covers/ubuntu-cover.png", "Claude Code running in an Ubuntu terminal", """<p>Claude Code is Anthropic’s agentic coding tool for the terminal. It can understand a codebase, propose edits, run tests, and help with Git workflows. This guide keeps the setup simple and uses copy-ready commands.</p><blockquote><p><strong>Requirements:</strong> Ubuntu 20.04+ or Debian 10+, at least 4 GB RAM, internet access, and Node.js 18 or newer.</p></blockquote><h2>1. Install Node.js and Git</h2><pre><code>sudo apt update\nsudo apt install -y nodejs npm git\nnode --version\nnpm --version\ngit --version</code></pre><p><strong>Expected:</strong> Each command prints a version. If Node is older than version 18, install a current Node.js release using your organization’s approved Node source before continuing.</p><h2>2. Install Claude Code</h2><p>Install the official package globally as your normal user. Do not use <code>sudo npm install -g</code>.</p><pre><code>npm install -g @anthropic-ai/claude-code\nclaude --version</code></pre><p><strong>Expected:</strong> npm finishes successfully, followed by a Claude Code version number. If npm reports a permissions error, fix your npm global-prefix setup rather than rerunning with sudo.</p><h2>3. Check the installation health</h2><pre><code>claude doctor</code></pre><p><strong>Expected:</strong> Claude Code reports its installation type and any recommended actions.</p><h2>4. Start Claude Code in a project</h2><pre><code>mkdir -p ~/Projects/claude-demo\ncd ~/Projects/claude-demo\ngit init\nclaude</code></pre><p><strong>Expected:</strong> Claude Code opens its interactive session and asks you to authenticate. Select the option matching your Anthropic Console account, Claude Pro/Max account, or approved enterprise provider. Complete the browser sign-in and return to the terminal.</p><h2>5. Start with a safe prompt</h2><p>In the interactive session, ask:</p><pre><code>Explain the files in this project. Do not modify files or run shell commands.</code></pre><p><strong>Expected:</strong> Claude describes the repository without making changes. Review every proposed command and edit before approving it.</p><h2>6. Useful everyday commands</h2><pre><code>claude \"explain this project\"\nclaude -p \"list likely test commands for this repository\"\nclaude -c\nclaude update</code></pre><ul><li><code>claude \"…\"</code> starts a session with an initial prompt.</li><li><code>claude -p \"…\"</code> prints a response and exits—useful in scripts.</li><li><code>claude -c</code> continues the most recent conversation.</li><li><code>claude update</code> requests the latest version.</li></ul><h2>7. Protect your project</h2><p>Make a Git checkpoint before broad agent tasks and inspect changes afterward:</p><pre><code>git add -A\ngit commit -m \"Checkpoint before Claude task\"\ngit diff\ngit status</code></pre><p>Avoid <code>--dangerously-skip-permissions</code> unless you fully understand the command and are working in a disposable environment. The <a href=\"https://docs.anthropic.com/en/docs/claude-code/getting-started\">official Claude Code setup guide</a> and <a href=\"https://docs.anthropic.com/en/docs/claude-code/cli-usage\">CLI reference</a> are the source of truth for current options.</p>"""),
]

def shell(slug, title, description, minutes, words, cover, alt, content):
    cover = {"/images/codex-cli-banner.png": "/images/covers/codex-ubuntu-cli-banner.png", "/images/covers/ubuntu-cover.png": "/images/covers/claude-ubuntu-cli-banner.png"}.get(cover, cover)
    return f'''<!doctype html><html lang=en dir=auto data-theme=dark><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><meta name=robots content="index, follow"><title>{title} | Aayrix</title><meta name=description content="{description}"><link rel=canonical href="https://ayrix.online/posts/{slug}/"><link rel=stylesheet href=/assets/css/stylesheet.4ea0df3983f223cad367032f4b80a5ef62ddcd0a18dcab9c723feaeb274b6e7c.css><link rel=stylesheet href=/assets/css/ayrix-motion.css><link rel=stylesheet href=/assets/css/ayrix-redesign.css><meta property="og:type" content="article"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:url" content="https://ayrix.online/posts/{slug}/"><meta property="article:published_time" content="{iso}"></head><body id=top><header class=header><nav class=header-nav><div class=logo><a href=/>Aayrix</a></div><ul class=menu><li><a href=/>Home</a></li><li><a href=/posts/>Publications</a></li><li><a href=/tags/>Tags</a></li><li><a href=/categories/>Categories</a></li><li><a href=/about/>About Me</a></li><li><a href=/contact/>Contact</a></li></ul></nav></header><main class=main><article class=post-single><header class=post-header><nav class=breadcrumbs><a href=/>Home</a> / <a href=/posts/>Publications</a></nav><h1 class=post-title>{title}</h1><div class=post-description>{description}</div><div class=post-meta><span>{date}</span>&nbsp;·&nbsp;<span>{minutes}</span>&nbsp;·&nbsp;<span>{words} words</span>&nbsp;·&nbsp;<span>Aliyan</span></div></header><figure class=entry-cover><img loading=eager src="{cover}" alt="{alt}"></figure><div class="post-content md-content">{content}</div><footer class=post-footer><ul class=post-tags><li><a href=/tags/git/>Git</a></li><li><a href=/tags/linux/>Linux</a></li><li><a href=/tags/developer/>Developer</a></li></ul></footer></article></main><footer class=footer><span>© 2026 Aayrix. All rights reserved.</span> · <span>Built with HTML &amp; CSS</span></footer></body></html>'''

def card(post):
    slug, title, desc, minutes, words, cover, alt, _ = post
    cover = {"/images/codex-cli-banner.png": "/images/covers/codex-ubuntu-cli-banner.png", "/images/covers/ubuntu-cover.png": "/images/covers/claude-ubuntu-cli-banner.png"}.get(cover, cover)
    return f'<article class=post-entry><figure class=entry-cover><img loading=lazy src="{cover}" alt="{alt}"></figure><header class=entry-header><h2 class=entry-hint-parent>{title}</h2></header><div class=entry-content><p>{desc}</p></div><footer class=entry-footer><span>{date}</span>&nbsp;·&nbsp;<span>{minutes}</span>&nbsp;·&nbsp;<span>{words} words</span>&nbsp;·&nbsp;<span>Aliyan</span></footer><a class=entry-link aria-label="post link to {title}" href=/posts/{slug}/></a></article>'

for post in posts:
    slug = post[0]
    path = public / "posts" / slug / "index.html"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(shell(*post), encoding="utf-8")

cards = "".join(card(post) for post in posts)
for page in (public / "posts/index.html", public / "index.html"):
    html = page.read_text(encoding="utf-8")
    if all(f'/posts/{post[0]}/' not in html for post in posts):
        page.write_text(html.replace('<article class=post-entry>', cards + '<article class=post-entry>', 1), encoding="utf-8")

listing = public / "posts/index.html"
listing_html = listing.read_text(encoding="utf-8")
listing_html = listing_html.replace('src="/images/codex-cli-banner.png" alt="OpenAI Codex CLI on Ubuntu"', 'src="/images/covers/codex-ubuntu-cli-banner.png" alt="OpenAI Codex CLI on Ubuntu"')
listing_html = listing_html.replace('src="/images/covers/ubuntu-cover.png" alt="Claude Code running in an Ubuntu terminal"', 'src="/images/covers/claude-ubuntu-cli-banner.png" alt="Claude Code running in an Ubuntu terminal"')
listing.write_text(listing_html, encoding="utf-8")

# The homepage uses a curated card grid rather than post-entry elements.
home = public / "index.html"
home_html = home.read_text(encoding="utf-8")
if '/posts/codex-cli-ubuntu-openai-agent-guide/' not in home_html:
    featured = '<div class=section-header><span class=section-label>New guides</span><h2>AI Agents in Your Terminal</h2><p class=section-subtitle>Professional Ubuntu setup guides for practical, safe coding workflows.</p></div><div class="home-cards guides"><a class="home-card guide-card" href=/posts/codex-cli-ubuntu-openai-agent-guide/><span class=home-card-icon>✦</span><span class=home-card-title>Codex CLI on Ubuntu</span><span class=home-card-desc>Install Codex, connect your OpenAI account, and work safely.</span></a><a class="home-card guide-card" href=/posts/claude-code-ubuntu-cli-guide/><span class=home-card-icon>◈</span><span class=home-card-title>Claude Code on Ubuntu</span><span class=home-card-desc>Professional installation, sign-in, and CLI workflow guide.</span></a></div>'
    home_html = home_html.replace('<div class=section-header><span class=section-label>Expertise', featured + '<div class=section-header><span class=section-label>Expertise', 1)
    home_html = home_html.replace('>7+</span><span class=home-stat-label>Published Guides', '>10+</span><span class=home-stat-label>Published Guides', 1)
    home.write_text(home_html, encoding="utf-8")

sitemap = public / "sitemap.xml"
xml = sitemap.read_text(encoding="utf-8")
for post in posts:
    if post[0] not in xml:
        xml = xml.replace('</urlset>', f'<url><loc>https://ayrix.online/posts/{post[0]}/</loc><lastmod>{iso}</lastmod></url></urlset>')
sitemap.write_text(xml, encoding="utf-8")
print("Added two developer posts and updated their site listings.")
